exercise.solution:
fn main() {
    let words = ["rust", "is", "fun"];
    let total: usize = words.iter().map(|w| w.len()).sum();
    println!("{total}");
    let long = words.iter().filter(|w| w.len() > 2).count();
    println!("{long}");
}
